package com.rikkeibank.identity.service;
import com.rikkeibank.common.api.BusinessException; import com.rikkeibank.identity.domain.*; import com.rikkeibank.identity.repo.*; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import java.util.concurrent.TimeUnit;
@Service public class AuthService {
 private final UserRepository users; private final RefreshTokenRepository tokens; private final PasswordEncoder passwords; private final StringRedisTemplate redis; private final byte[] secret; private final Duration accessTtl; private final Duration refreshTtl;
 public AuthService(UserRepository u,RefreshTokenRepository t,PasswordEncoder p,StringRedisTemplate r,@Value("${security.jwt.secret}")String s,@Value("${security.jwt.access-ttl:PT15M}")Duration a,@Value("${security.jwt.refresh-ttl:P30D}")Duration f){users=u;tokens=t;passwords=p;redis=r;secret=s.getBytes(StandardCharsets.UTF_8);accessTtl=a;refreshTtl=f;}
 @Transactional public TokenPair login(String username,String password){AppUser user=users.findByUsername(username).filter(AppUser::isActive).orElseThrow(()->unauthorized());if(!passwords.matches(password,user.getPasswordHash()))throw unauthorized();return issue(user);}
 @Transactional public TokenPair refresh(String raw){RefreshToken old=tokens.findByTokenHash(hash(raw)).filter(RefreshToken::valid).orElseThrow(()->unauthorized());old.revoke();AppUser user=users.findById(old.getUserId()).filter(AppUser::isActive).orElseThrow(()->unauthorized());return issue(user);}
 @Transactional public void revoke(UUID userId){if(!users.existsById(userId))throw BusinessException.notFound("User not found");tokens.deleteByUserId(userId);redis.opsForValue().set("auth:revoked:"+userId,"1",accessTtl.toSeconds(),TimeUnit.SECONDS);}
 private TokenPair issue(AppUser u){Instant now=Instant.now(),exp=now.plus(accessTtl);String access=Jwts.builder().subject(u.getId().toString()).claim("username",u.getUsername()).claim("roles",List.of(u.getRole().name())).claim("customerId",u.getCustomerId()==null?null:u.getCustomerId().toString()).issuedAt(Date.from(now)).expiration(Date.from(exp)).signWith(Keys.hmacShaKeyFor(secret)).compact();String refresh=random();tokens.save(new RefreshToken(hash(refresh),u.getId(),now.plus(refreshTtl)));redis.delete("auth:revoked:"+u.getId());return new TokenPair(access,refresh,"Bearer",accessTtl.toSeconds());}
 private String random(){byte[] b=new byte[48];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);} private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private BusinessException unauthorized(){return new BusinessException(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","Invalid credentials or expired token");}
 public record TokenPair(String accessToken,String refreshToken,String tokenType,long expiresIn){}
}

